export type ParsedLockDepositInstruction<
  TProgram extends string = typeof SHARED_DEPOSIT_PASSPORT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    merchantSigner: TAccountMetas[0];
    passport: TAccountMetas[1];
    merchant: TAccountMetas[2];
    depositAccount: TAccountMetas[3];
    authorization: TAccountMetas[4];
    rentalLock: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: LockDepositInstructionData;
};

export function parseLockDepositInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedLockDepositInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      merchantSigner: getNextAccount(),
      passport: getNextAccount(),
      merchant: getNextAccount(),
      depositAccount: getNextAccount(),
      authorization: getNextAccount(),
      rentalLock: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getLockDepositInstructionDataDecoder().decode(instruction.data),
  };
}
